<script lang="ts" setup>
import { animate, svg } from 'animejs'
import { ref, watch, onMounted } from 'vue'

const pathData = ref('')
const isDrawing = ref(false)
const autoMorph = ref(true)
let morphing = false
let currentAnimation: any = null

onMounted(() => {
  const canvas = document.getElementById('drawingCanvas') as HTMLCanvasElement
  const ctx = canvas.getContext('2d')!
  canvas.width = 640
  canvas.height = 480

  let lastX = 0, lastY = 0

  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect()
    isDrawing.value = true
    const x = e.clientX - rect.left
    const y = e.clientY - rect.top
    lastX = x
    lastY = y
    pathData.value = `M${x},${y}`
  })

  canvas.addEventListener('mousemove', (e) => {
    if (!isDrawing.value) return
    const rect = canvas.getBoundingClientRect()
    const currentX = e.clientX - rect.left
    const currentY = e.clientY - rect.top

    ctx.beginPath()
    ctx.moveTo(lastX, lastY)
    ctx.lineTo(currentX, currentY)
    ctx.strokeStyle = '#3cf2fc'
    ctx.lineWidth = 2
    ctx.stroke()

    pathData.value += ` L${currentX},${currentY}`
    lastX = currentX
    lastY = currentY
  })

  canvas.addEventListener('mouseup', () => {
    isDrawing.value = false
  })

  canvas.addEventListener('mouseleave', () => {
    if (isDrawing.value) {
      isDrawing.value = false
    }
  })
})

watch([pathData, isDrawing], ([newPath, drawing]) => {
  if (newPath && !drawing && autoMorph.value && !morphing) {
    startMorph()
  }
})

const startMorph = () => {
  if (morphing) return
  morphing = true

  const sourcePath = document.getElementById('sourcePath') as unknown as SVGPathElement
  const targetPath = document.getElementById('targetPath') as unknown as SVGPathElement

  sourcePath.setAttribute('d', pathData.value)

  if (currentAnimation) {
    currentAnimation.pause()
    currentAnimation = null
  }

  currentAnimation = animate(sourcePath, {
    d: svg.morphTo(targetPath),
    duration: 1500,
    ease: 'easeInOutQuad',
    onUpdate: () => {
      const currentD = sourcePath.getAttribute('d') || ''
      redrawCanvas(currentD)
    },
    onComplete: () => {
      morphing = false
      currentAnimation = null
    }
  })
}

const redrawCanvas = (d: string) => {
  const canvas = document.getElementById('drawingCanvas') as HTMLCanvasElement
  const ctx = canvas.getContext('2d')!
  ctx.clearRect(0, 0, canvas.width, canvas.height)

  if (!d) return

  ctx.strokeStyle = '#3cf2fc'
  ctx.lineWidth = 2
  ctx.lineJoin = 'round'
  ctx.lineCap = 'round'

  try {
    const path = new Path2D(d)
    ctx.stroke(path)
  } catch (error) {
    console.warn('无法重绘当前 SVG 路径:', error)
  }
}

const clearCanvas = () => {
  const canvas = document.getElementById('drawingCanvas') as HTMLCanvasElement
  const ctx = canvas.getContext('2d')!
  ctx.clearRect(0, 0, canvas.width, canvas.height)
  pathData.value = ''
  document.getElementById('sourcePath')?.setAttribute('d', '')
  morphing = false
  if (currentAnimation) {
    currentAnimation.pause()
    currentAnimation = null
  }
}

const toggleAutoMorph = () => {
  autoMorph.value = !autoMorph.value
}
</script>

<style lang="scss" scoped>
.path-stage {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
}
canvas {
  border: 1px solid #ccc;
  cursor: crosshair;
  display: block;
  margin-bottom: 10px;
  background: #1a1a1a;
}
button {
  margin-right: 10px;
  padding: 8px 16px;
  cursor: pointer;
}
</style>
